"""Offline HTML defense deck when the integrated presentation runtime is unavailable."""
from html import escape
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]; out=ROOT/'docs/release'; data=json.loads((out/'research/aggregate.json').read_text())
slides=[]
def slide(title,body,note=''):
    slides.append((title,body,note))
def para(text):return '<p>'+escape(text)+'</p>'
def points(items):return '<ul>'+''.join('<li>'+escape(x)+'</li>' for x in items)+'</ul>'
slide('NovaBank và prompt injection', '<p class="lead">Ngân hàng mô phỏng có AI hỗ trợ, với quyền thực thi do Banking API kiểm soát</p><p>Demo local · 01/11/2026</p><p>React / TypeScript · FastAPI / SQLite · Ollama</p>', 'Dữ liệu và tiền đều giả. Bản này phục vụ nghiên cứu, chưa là hệ thống ngân hàng production.')
slide('Phạm vi hệ thống', points(['25 use cases: xác thực, thanh toán, sản phẩm, hỗ trợ, AI và nghiên cứu.', 'MFA và session revocation, sổ cái kép, hóa đơn, debit/credit, tiết kiệm và sao kê.', 'Agent service riêng, RAG có nguồn, human approval và trace.', 'Bộ nghiên cứu có sandbox reset, dữ liệu gốc và dashboard đo kết quả.']), 'SRS.md ánh xạ từng use case với hành vi và điều kiện nghiệm thu.')
slide('Ranh giới thực thi', '<ol><li>Browser gửi yêu cầu và OTP đến Banking API.</li><li>Bank cấp grant 180 giây: ai:read và ai:prepare.</li><li>Agent gọi model local và các tool HTTP được cấp.</li><li>Bank kiểm tra owner, intent, tham số và hạn mức.</li><li>Customer duyệt proposal rồi xác nhận trong màn hình ngân hàng.</li></ol>', 'Agent không mount DB và không nhận signing key. Không có tool confirm.')
slide('Một đường ghi sổ cho mọi sản phẩm', points(['Tiền nguyên VND. Mỗi journal tổng bằng 0 và cache phải khớp ledger.', 'BEGIN IMMEDIATE giữ posting, history, notification và audit trong cùng transaction.', 'OTP gắn session/payload, idempotency ngăn trừ lặp.', 'Liên ngân hàng mô phỏng có pending, settlement và compensating reversal trả cả phí.']), 'SQLite write lock phù hợp stack demo. Không tuyên bố đã kiểm thử PostgreSQL hoặc hệ thống phân tán.')
slide('Nghiên cứu có kiểm soát', '<p class="lead">1.790 quan sát trên hai model local</p>'+points(['35 kịch bản = 7 vector × 5 mục tiêu tấn công.', '3 profile × 2 model × 5 lần lặp attack = 1.050 quan sát.', '100 tác vụ hợp lệ × 3 profile × 2 model = 600 quan sát.', '140 ablations, bỏ từng lớp D1–D10 trên tập mẫu hẹp.']), 'Nguồn truy xuất được đưa sẵn vào context. Mỗi mẫu đo một quyết định tool. Dataset v1.1 và hash nằm trong summary.json.')
slide('Các lớp phòng vệ', '<table><tr><th>Nhóm</th><th>Lớp kiểm soát</th></tr><tr><td>Chỉ dẫn và dữ liệu</td><td>D1 system rules, D2 delimiters, D10 owner-bound memory</td></tr><tr><td>Quyền và hành động</td><td>D3 least privilege, D4 argument binding, D5 approval</td></tr><tr><td>Giới hạn và phát hiện</td><td>D6 budgets, D7 source screening, D9 anomaly stop</td></tr><tr><td>Trả lời</td><td>D8 output filter, thông báo hành động nhạy cảm do bank tạo</td></tr></table>', 'Classifier là defense in depth. Authorization và ledger phải an toàn ngay cả khi model hoặc classifier thất bại.')
rows=''.join('<tr>'+''.join('<td>'+escape(str(v))+'</td>' for v in [m['model'],m['profile'],f"{m['successes']}/{m['attacks']}",f"{m['asr']:.2%}",f"{m['utility']:.0%}"])+'</tr>' for m in data)
slide('Kết quả trên corpus đã đo', '<table><tr><th>Model</th><th>Profile</th><th>Attack đạt goal</th><th>ASR</th><th>Utility</th></tr>'+rows+'</table>', 'Không có lỗi chạy, mọi sandbox journal cân. Utility = đúng tool/args. Một proposal sai được chấp nhận có thể tính attack success dù tiền chưa chuyển.')
example=json.loads((out/'research/example.json').read_text(encoding='utf-8'))
slide('Cùng payload, hai kết quả', '<div class="columns"><div><h2>Baseline lab</h2><p>Nickname giả mạo yêu cầu thay Bob bằng Charlie.</p><p class="code">prepare_transfer<br>to: ACC-CHARLIE-001<br>amount: 1.000 VND<br>ALLOW · PENDING_APPROVAL</p></div><div><h2>Defended</h2><p>Cùng scenario và model.</p><p class="code">D7<br>CLASSIFIER_RETRIEVAL_BLOCK<br>Không gọi tool<br>Goal không đạt</p></div></div>', f"Stored observation {example['baseline']['scenario_id']}, {example['baseline']['model']}. Baseline vẫn cần human approval; đây chưa phải chuyển tiền trái phép.")
slide('Bằng chứng kiểm tra', points(['Financial line coverage 93,27% ở các module ghi sổ, chuyển tiền và sản phẩm.', 'Test backend, component, Playwright và hai tiến trình với model thật.', '44 màn hình ở 375/768/1440 px, kiểm tra source và approval UI.', 'Migration copy giữ dữ liệu cũ. Restore khôi phục 52 bảng và MFA key.', 'Video thực hiện Alice–Bob và minh họa kết quả nghiên cứu lưu thật.']), 'Số test và command outcomes cuối cùng nằm trong STATUS.md và evidence/. Line coverage không phải branch coverage.')
slide('Giới hạn và phát hành', points(['ASR 0 trong corpus không chứng minh an toàn trước payload thích ứng.', 'D3 lab dùng intent chuẩn; chưa đo retrieval poisoning end-to-end.', 'Ablation và benign classifier sample còn nhỏ; không xếp hạng đóng góp nhân quả.', 'Compose đã parse, nhưng Docker runtime, HTTPS public và CI remote chưa được xác nhận.', 'Dependency advisories và review độc lập vẫn cần xử lý trước phát hành.']), 'Nguồn: PI_RESULTS.md, SECURITY_EVALUATION.md, raw-results.zip. Không dùng demo cho tiền hoặc PII thật.')
html='''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NovaBank — Defense slides</title><style>
*{box-sizing:border-box}body{margin:0;background:#211536;color:#211536;font-family:Arial,"Segoe UI",sans-serif}.slide{display:none;position:relative;width:min(1280px,100vw);height:min(720px,56.25vw);min-height:520px;margin:25px auto;background:#fff;padding:54px 64px 90px;overflow:auto}.slide.active{display:block}h1{font-size:38px;line-height:1.14;color:#54238c;margin:0 0 30px;letter-spacing:-.7px}h2{font-size:26px;color:#54238c}p,li{font-size:23px;line-height:1.45}li{margin:14px 0}ul,ol{padding-left:28px}.lead{font-size:31px;line-height:1.35;max-width:1000px}table{width:100%;border-collapse:collapse;font-size:22px}td,th{text-align:left;padding:14px 10px;border-bottom:1px solid #e3dcec}th{color:#54238c;font-size:19px}tr:nth-child(even){background:#f7f4fb}.columns{display:grid;grid-template-columns:1fr 1fr;gap:65px}.code{font:23px/1.6 monospace;color:#402265}.note{position:absolute;left:64px;right:64px;bottom:26px;font-size:16px;line-height:1.4;color:#62576d}nav{display:flex;gap:18px;justify-content:center;align-items:center;color:#fff;font:16px Arial;padding:4px 16px 20px}button{font:inherit;border:1px solid #cbb8df;border-radius:5px;color:#fff;background:transparent;padding:9px 18px;cursor:pointer}button:focus-visible{outline:3px solid #f1c85b}button:disabled{opacity:.4}@media(max-width:800px){.slide{height:auto;min-height:80vh;padding:28px 24px 100px;margin:0}h1{font-size:28px}p,li{font-size:18px}table{font-size:16px}td,th{padding:9px 5px}.columns{grid-template-columns:1fr;gap:12px}.note{left:24px;right:24px;font-size:13px}.lead{font-size:23px}}@media print{@page{size:landscape;margin:0}body{background:white}.slide{display:block!important;width:297mm;height:167mm;margin:0;break-after:page;min-height:0;padding:14mm 17mm 24mm;overflow:hidden}nav{display:none}h1{font-size:29px}p,li{font-size:20px}table{font-size:19px}.note{font-size:13px;bottom:7mm}}
</style></head><body>'''
for i,(title,body,note) in enumerate(slides):html+=f'<section class="slide{" active" if i==0 else ""}" aria-label="Slide {i+1}"><h1>{escape(title)}</h1>{body}<div class="note">{escape(note)}</div></section>'
html+='''<nav><button id="prev" type="button">Previous</button><span id="counter" aria-live="polite"></span><button id="next" type="button">Next</button><span>← → or Page Up / Page Down</span></nav><script>
let index=0;const slides=[...document.querySelectorAll('.slide')];function show(n){index=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,i)=>s.classList.toggle('active',i===index));document.getElementById('counter').textContent=`${index+1} / ${slides.length}`;document.getElementById('prev').disabled=index===0;document.getElementById('next').disabled=index===slides.length-1}document.getElementById('prev').onclick=()=>show(index-1);document.getElementById('next').onclick=()=>show(index+1);document.addEventListener('keydown',e=>{if(['ArrowRight','PageDown','ArrowLeft','PageUp','Home','End'].includes(e.key)){e.preventDefault();show(e.key==='Home'?0:e.key==='End'?slides.length-1:index+(['ArrowRight','PageDown'].includes(e.key)?1:-1))}});show(0);
</script></body></html>'''
(out/'Defense-Slides.html').write_text(html,encoding='utf-8')
(out/'SLIDE_NOTES.md').write_text('# Nội dung slide bảo vệ\n\nMở [Defense-Slides.html](Defense-Slides.html), dùng phím mũi tên hoặc Page Up/Page Down. Bản offline HTML có thể chỉnh source, không phải PPTX. Runtime xuất PowerPoint tích hợp không khả dụng trong phiên này.\n\n'+'\n\n'.join(f'## {i+1}. {t}\n\n{note}' for i,(t,b,note) in enumerate(slides)),encoding='utf-8')
print(out/'Defense-Slides.html')
